    def test_main_guard_no_stderr(self, module_path):
        """Running as script must not emit errors to stderr."""
        proc = subprocess.run(
            [sys.executable, str(module_path)],
            capture_output=True,
            text=True,
            timeout=10,
            check=False,
        )
        assert proc.stderr.strip() == "", f"Unexpected stderr: {proc.stderr}"

    def test_import_does_not_print(self, capsys):
        """Importing the module must not trigger stdout output."""
